#include "main.h"
#include "LCD.h"

uint32_t adcSamples[3];

void init_hw(){
  SystemClock=SysCtlClockFreqSet((SYSCTL_XTAL_25MHZ |
                               SYSCTL_OSC_MAIN |
                               SYSCTL_USE_PLL |
                               SYSCTL_CFG_VCO_480), 120000000);
	//freq 120MHz

    SysCtlPeripheralEnable(SYSCTL_PERIPH_TIMER0);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_TIMER1);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOF);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOK);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOE);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOA);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOC);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_ADC0);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_UART0);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPION);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOL);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_PWM0);
    while(!SysCtlPeripheralReady(SYSCTL_PERIPH_ADC0)||!SysCtlPeripheralReady(SYSCTL_PERIPH_TIMER0)
            ||!SysCtlPeripheralReady(SYSCTL_PERIPH_UART0)||!SysCtlPeripheralReady(SYSCTL_PERIPH_GPIOK)
          ||!SysCtlPeripheralReady(SYSCTL_PERIPH_GPIOE)||!SysCtlPeripheralReady(SYSCTL_PERIPH_GPIOA)
        ||!SysCtlPeripheralReady(SYSCTL_PERIPH_GPION)||!SysCtlPeripheralReady(SYSCTL_PERIPH_GPIOL)
      ||!SysCtlPeripheralReady(SYSCTL_PERIPH_GPIOC)||!SysCtlPeripheralReady(SYSCTL_PERIPH_PWM0)
    ||!SysCtlPeripheralReady(SYSCTL_PERIPH_GPIOF)||!SysCtlPeripheralReady(SYSCTL_PERIPH_TIMER1)){};

    //PF2 de pwm
    GPIOPinConfigure(GPIO_PF2_M0PWM2);
    GPIOPinTypePWM(GPIO_PORTF_BASE,GPIO_PIN_2);
		PWMClockSet(PWM0_BASE, PWM_SYSCLK_DIV_1);
		//120MHz/8
		PWMGenConfigure(PWM0_BASE, PWM_GEN_1, PWM_GEN_MODE_DOWN | PWM_GEN_MODE_NO_SYNC);
		PWMGenPeriodSet(PWM0_BASE, PWM_GEN_1, (SystemClock /200000));//200kHz
    PWMPulseWidthSet(PWM0_BASE, PWM_OUT_2, 600 / 2);
		PWMGenEnable(PWM0_BASE, PWM_GEN_1);
		PWMOutputState(PWM0_BASE, PWM_OUT_2_BIT, true);

    //joystick button
    GPIODirModeSet(GPIO_PORTC_BASE, GPIO_PIN_6, GPIO_DIR_MODE_IN);
    GPIOPadConfigSet(GPIO_PORTC_BASE, GPIO_PIN_6, GPIO_STRENGTH_2MA, GPIO_PIN_TYPE_STD_WPU);
    GPIOIntTypeSet(GPIO_PORTC_BASE, GPIO_PIN_6, GPIO_FALLING_EDGE);
    GPIOIntEnable(GPIO_PORTC_BASE, GPIO_PIN_6);
		IntEnable(INT_GPIOC_TM4C129);

    //botões
    GPIODirModeSet(GPIO_PORTL_BASE, GPIO_PIN_1|GPIO_PIN_2, GPIO_DIR_MODE_IN);
    GPIOPadConfigSet(GPIO_PORTL_BASE, GPIO_PIN_1|GPIO_PIN_2, GPIO_STRENGTH_2MA, GPIO_PIN_TYPE_STD_WPU);
    GPIOIntTypeSet(GPIO_PORTL_BASE, GPIO_PIN_1|GPIO_PIN_2, GPIO_FALLING_EDGE);
    GPIOIntEnable(GPIO_PORTL_BASE, GPIO_PIN_1|GPIO_PIN_2);
		IntEnable(INT_GPIOL_TM4C129);


  GPIOPinConfigure(0x00000001);
						//TX
	GPIOPinConfigure(0x00000401);

  GPIOPinTypeUART(GPIO_PORTA_BASE,GPIO_PIN_0|GPIO_PIN_1);
		
	UARTConfigSetExpClk(UART0_BASE, SystemClock, 115200,
                        (UART_CONFIG_WLEN_8 | UART_CONFIG_STOP_ONE | UART_CONFIG_PAR_NONE));
	UARTStdioConfig(0, 115200, SystemClock);
		// UART0, Clock de 120MHz, Baud Rate 115200, 8-N-1 (8 bits, sem paridade, 1 stop bit)
  UARTConfigSetExpClk(UART0_BASE, SystemClock, 115200,
                        (UART_CONFIG_WLEN_8 | UART_CONFIG_STOP_ONE | UART_CONFIG_PAR_NONE));

  //config Timer0
  TimerConfigure(TIMER0_BASE, TIMER_CFG_PERIODIC);
  TimerLoadSet(TIMER0_BASE, TIMER_A, (SystemClock / 10000) - 1);
  TimerControlTrigger(TIMER0_BASE, TIMER_A, true);

  //config timer1
  TimerConfigure(TIMER1_BASE, TIMER_CFG_PERIODIC);
  TimerLoadSet(TIMER1_BASE, TIMER_A, (SystemClock / 10000) - 1);
  TimerIntEnable(TIMER1_BASE, TIMER_TIMA_TIMEOUT);
  IntEnable(INT_TIMER1A_TM4C129);
    //config ADC
  GPIOPinTypeADC(GPIO_PORTK_BASE, GPIO_PIN_0);
			
	GPIOPinTypeADC(GPIO_PORTE_BASE, GPIO_PIN_3|GPIO_PIN_4);						
    // Configure sequencer 0 to be triggered by a hardware timer
		//ADC0 nas portas PK0,AN16

  ADCSequenceConfigure(ADC0_BASE, 0, ADC_TRIGGER_TIMER, 0);	
  ADCSequenceStepConfigure(ADC0_BASE,0,0,ADC_CTL_CH16);
  ADCSequenceStepConfigure(ADC0_BASE,0,1,ADC_CTL_CH0);
  ADCSequenceStepConfigure(ADC0_BASE,0,2,ADC_CTL_CH9|ADC_CTL_IE | ADC_CTL_END);
  ADCSequenceEnable(ADC0_BASE,0);
  ADCIntClear(ADC0_BASE,0);

  //1ms para o threadX
  SysTickPeriodSet(SystemClock/ 1000);
  SysTickEnable();
  SysTickIntEnable();

  IntEnable(INT_ADC0SS0_TM4C129);

  TimerEnable(TIMER0_BASE, TIMER_A);
  //TimerEnable(TIMER1_BASE, TIMER_A);
}
