//thread
TX_THREAD           thread_filter;             // O "Objeto" da thread
TX_THREAD           thread_UI;
uint8_t             stack_filter[1024];
uint8_t             stack_UI[1024];
void thread_filter_entry(ULONG thread_input);
void thread_UIManager_entry(ULONG thread_input);

float32_t bufferA[BLOCK_SIZE];
float32_t bufferB[BLOCK_SIZE];

volatile int bufferAtivo = 0;      // 0 = A, 1 = B
volatile int posISR = 0;           // posição da ISR dentro do bloco
volatile bool bufferPronto = false; // thread DSP avisa ISR
//TX_SEMAPHORE semaforo_dados;
TX_QUEUE queue_amostras;
uint32_t queue_storage[NUM_AMOSTRAS];

void tx_application_define(void *first_unused_memory){
  tx_queue_create(&queue_amostras,
                "fila_adc",
                TX_1_ULONG,           // tamanho do item = 1 ULONG (4 bytes)
                queue_storage,
                sizeof(queue_storage));
  //tx_semaphore_create(&semaforo_dados, "SemDados", 0);
  tx_thread_create(&thread_filter,"ThreadFiltro",thread_filter_entry,0,stack_filter,sizeof(stack_filter),
  1,1,TX_NO_TIME_SLICE,TX_AUTO_START);
  tx_thread_create(&thread_UI,"ThreadUI",thread_UIManager_entry,0,stack_UI,sizeof(stack_UI),
  2,2,TX_NO_TIME_SLICE,TX_AUTO_START);
}
volatile bool first_run=true;

void thread_filter_entry(ULONG thread_input){
    uint32_t new_data;
    float32_t bufferProcessamento[BLOCK_SIZE];
    float32_t bufferProcessado[BLOCK_SIZE];
    ADCIntEnable(ADC0_BASE, 0);	
    arm_fir_init_f32(&S_FIR, NUM_TAPS, (float32_t*)fir_coeffs[filter][freq], fir_state, BLOCK_SIZE);

    while(1){  
      if (update_filter_needed) {
          if (filter > 2) filter = 0;
          if (freq > 9) freq = 9;

          arm_fir_init_f32(&S_FIR, NUM_TAPS, 
                          (float32_t*)fir_coeffs[filter][freq], 
                          fir_state, BLOCK_SIZE);
          
          //UARTprintf("Filtro Atualizado: Tipo %d, Freq %d Hz\n", filter, freqs[freq]);
          update_filter_needed = false; 
      }


    
        for (int i = 0; i < BLOCK_SIZE; i++) {
          tx_queue_receive(&queue_amostras, &new_data, TX_WAIT_FOREVER);
          bufferProcessamento[i] = (float32_t)new_data - 2048.0f;  
					//UARTprintf("Entrada:%d \n ", new_data);
        }

    arm_fir_f32(&S_FIR, bufferProcessamento, bufferProcessado, BLOCK_SIZE);
      if (bufferAtivo == 0) {
            for (int i=0; i < BLOCK_SIZE; i++){
                float32_t sinal_adc = bufferProcessado[i]+ 2048.0f;

                if (sinal_adc < 0) sinal_adc = 0;
                if (sinal_adc > 4095) sinal_adc = 4095;

                float32_t sinal_pwm = (sinal_adc * 600.0f) / 4096.0f;
                bufferB[i] = sinal_pwm;
							//UARTprintf("Saida:%d  \n", (int16_t)sinal_pwm);
            }
						//UARTprintf("Usando bufferB\n");
        } else {
            // ISR está tocando B → escrevo no A
            for (int i=0; i < BLOCK_SIZE; i++){
                float32_t sinal_adc = bufferProcessado[i]+ 2048.0f;

                if (sinal_adc < 0) sinal_adc = 0;
                if (sinal_adc > 4095) sinal_adc = 4095;

                float32_t sinal_pwm = (sinal_adc * 600.0f) / 4096.0f;
                bufferA[i] = sinal_pwm;
							//UARTprintf("Saida:%d  \n", (int16_t)sinal_pwm);
            }
        }
				//UARTprintf("UsandoBufferB\n");

        // Marca como pronto → ISR troca quando terminar o bloco atual
      bufferPronto = true;
				if(first_run){
					TimerEnable(TIMER1_BASE,TIMER_A);
					first_run=false;
				}
  }
}

void thread_UIManager_entry(ULONG thread_input){
  DisplaySetup();
  DesenharTelaPrincipal();
  while(1){
    IHM_Loop();
    tx_thread_sleep(500);
}
}

extern volatile ULONG _tx_timer_system_clock;

//


//interrupção
void ADC0SS0_Handler(void)
{
  ADCIntClear(ADC0_BASE, 0);
  ADCSequenceDataGet(ADC0_BASE, 0, (uint32_t*)adcSamples);
  tx_queue_send(&queue_amostras, &adcSamples[0], TX_NO_WAIT);
  
}
volatile ULONG tempo_joystick=0;
void GPIOC_Handler(void){
	 uint32_t status=GPIOIntStatus(GPIO_PORTC_BASE, true);
	 GPIOIntClear(GPIO_PORTC_BASE, status);
   ULONG tempo_atual=tx_time_get();
   if(tempo_atual-tempo_joystick>DEBOUNCE){
      button_joystick=true;
      tempo_joystick=tempo_atual;
   }

	 
} 
volatile ULONG ultimo_tempo1=0;
volatile ULONG ultimo_tempo2=0;
void GPIOL_Handler(void){
	 uint32_t status=GPIOIntStatus(GPIO_PORTL_BASE, true);
	 GPIOIntClear(GPIO_PORTL_BASE, status);
   if(status & GPIO_PIN_1){
    ULONG tempo_atual1 = tx_time_get();
    if(tempo_atual1-ultimo_tempo1>DEBOUNCE){
      if(modo_filter==2){
        modo_filter=0;
      }
      else
        modo_filter++;
      ultimo_tempo1=tempo_atual1;
      button_1=true;
    }
  }

   else if(status & GPIO_PIN_2){
    ULONG tempo_atual2 = tx_time_get();
    if(tempo_atual2-ultimo_tempo2>DEBOUNCE){
      button_2=true;
      ultimo_tempo2=tempo_atual2;
    }
   }
} 

void TIMER1A_Handler(void) {
    TimerIntClear(TIMER1_BASE, TIMER_TIMA_TIMEOUT);

    float32_t valor;

    if (bufferAtivo == 0){
			valor = bufferA[posISR];
		}
    else{
			valor = bufferB[posISR];
		}
    uint32_t pwm = (uint32_t) valor;
    PWMPulseWidthSet(PWM0_BASE, PWM_OUT_2, pwm);

    posISR++;
		//UARTprintf("Buffer:%d , pos:%d\n ",bufferAtivo,posISR);
    // Chegou no fim do bloco?
    if (posISR == BLOCK_SIZE) {
        posISR = 0;
        // Só troca se a thread já tiver produzido o outro bloco
        if (bufferPronto) {
            bufferAtivo ^= 1;   // Alterna A→B ou B→A
            bufferPronto = false;
        }
			}
}

